"""Карта ~300 статей: кандидаты из z32 (после синонимов) → хабы по ключевым словам головы.
Порог головы подбирается так, чтобы статей было около TARGET. Выдачей не проверено.
Выход: seo/05-karta-300.csv. Запуск: python3 dlya-mam/scripts/article_map_auto.py [TARGET]"""
import csv, os, re, sys, subprocess, collections
ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')
TARGET = int(sys.argv[1]) if len(sys.argv) > 1 else 300
HUBS = [  # (хаб, рецензент, регулярка по фразе) — первая подходящая
 ('Ночью и скорая', 'педиатр', r'скор|неотложн|вызыва'),
 ('Неврология и ортопедия', 'педиатр', r'на носочках|носочках|тонус|кривоше|дисплаз|тазобедр|тремор|невролог|косолап|плоскостоп'),
 ('Прививки', 'педиатр', r'привив|вакцин|календар|бцж|манту|реакци[яи] на'),
 ('Кожа', 'дерматолог', r'\bсып|крапивниц|дерматит|потниц|акне|прыщ|себоре|корочк|пятн|экзем|шелуш|сухая кожа|кожа|розеол|ветрян|аллерги'),
 ('Кашель и дыхание', 'педиатр', r'кашл|кашель|бронх|пневмон|круп|хрип|дыхан|дыш|одышк'),
 ('Нос, горло, уши, глаза', 'педиатр', r'насморк|сопл|\bнос\b|\bноса\b|\bносу\b|носик|для носа|горл|отит|\bух[оау]\b|\bушк|\bушей|глаз|конъюнктив|слез|орви|простуд'),
 ('Сон и режим', 'педиатр', r'спит на животе|просыпается|\bсон\b|\bсна\b|спит|спать|засып|режим|ночью не спит|укачив'),
 ('Живот и стул', 'педиатр', r'\bпонос|лактазн|рвот|рвет|понос|диаре|запор|стул|какает|кака|колик|газик|живот|срыгив|икот|ротавирус|кишечн|отравлен|ацетон|лактазн'),
 ('Температура', 'педиатр', r'температур|жар|лихорад'),
 ('Грудное вскармливание', 'педиатр', r'грудн|грудь|лактац|лактост|мастит|сцежив|молок|сос[ок]|кормящ|гв\b'),
 ('Искусственное вскармливание', 'педиатр', r'смес|искусствен|бутылоч|пустышк|соск'),
 ('Прикорм', 'педиатр', r'прикорм|пюре|каш[аиу]|кабачок|овощ|мяс[оа]|желток|яйц|творог|кефир|фрукт|меню|питани'),
 ('Развитие по месяцам', 'педиатр', r'месяц|уме[ею]т|развити|ползает|ползать|сидит|сидеть|ходит|ходить|говорит|говорить|переворач|держит голову|гуление|первые слова|шаги'),
 ('Вес и рост', 'педиатр', r'вес\b|веса|весит|прибав|рост\b|роста'),
 ('Зубы и рот', 'педиатр', r'прорезыв|зуб|десн|стоматит|молочниц'),
 ('Плач и поведение', 'педиатр', r'плач|плачет|капризн|кричит|истерик'),
 ('Неврология и ортопедия', 'педиатр', r'тонус|гипертонус|гипотонус|кривошея|дисплази|тазобедрен|тремор|судорог|невролог'),
 ('Анализы и показатели', 'педиатр', r'анализ|гемоглобин|анеми|витамин|рахит|ферритин|моч[аи]|кров[ьи] у'),
 ('Новорождённый и уход', 'педиатр', r'желтух|желтушк|билирубин|бассейн|новорожд|пуп|купан|уход|прогул|массаж|гимнастик|желтушк|родничок|скрининг|узи|осмотр|выписк|роддом'),
]
def hub_of(p):
    for h, rev, rx in HUBS:
        if re.search(rx, p): return h, rev
    return 'Прочее', 'педиатр'
def run(head):
    subprocess.run([sys.executable, os.path.join(ROOT, 'scripts', 'wordstat_core.py'), str(head), '50'], check=True, capture_output=True)
    return list(csv.DictReader(open(os.path.join(ROOT, 'zamery', 'z32-lex-clusters.csv'), encoding='utf-8')))
QUOTA = {'Новорождённый и уход': 33, 'Кожа': 25, 'Грудное вскармливание': 25, 'Прикорм': 25, 'Развитие по месяцам': 25,
 'Живот и стул': 22, 'Температура': 20, 'Нос, горло, уши, глаза': 20, 'Кашель и дыхание': 18, 'Сон и режим': 15, 'Прививки': 15,
 'Вес и рост': 10, 'Зубы и рот': 10, 'Анализы и показатели': 10, 'Искусственное вскармливание': 8, 'Неврология и ортопедия': 8, 'Неврология и ортопедия ': 0,
 'Плач и поведение': 6, 'Ночью и скорая': 5}
JUNK = r'машинк|лактазар|\bгель|успокаивающ|леща|лещ|карас|рыбалк|глист|энтеробиоз|форум|животные для детей|коран|молитв|в саду|зуба мудрости|пульмикорт|непослушн|машины детям|дети плач т|\bберет\b|шапк|молоко маленькое|для рыбы|рр4|отцы и дети|энтеробиоз|хорошие дети|плач ребенка звук|носочки для|успокаивающая|дети после сна|сон спящий|сон маленький|нутрилак|не хочет ходить|просыпается ночью|девочк|мальчик|человек|групп[аы] новор|отделени|реанимац|патолог|клинические рекомендации|размер|возраст|видео|своими руками|товар|набор|комплект|костюм|кофточк|пряж|весы|\bсад\b|школ|пусть говорят|во сне|перед сном|мама с новорожд|новорожденные в роддоме|новорожденный дома|после родов|маленький новорожденный|признаки новорожденного|как понять что у новорожденного|дают новорожденному|новорожденный кушает|как помочь новорожденному|позы для|столбиком|синдром у новорожденных|состояния новорожденных'
MERGE = {'новорожденный желтый':'желтушка у новорожденных','сколько набирают новорожденные':'прибавка в весе у новорожденных','акне новорожденных на лице':'акне новорожденных','новорожденный икает после кормления':'новорожденный икает','кабачок для прикорма как приготовить':'кабачок для прикорма','сколько варить кабачок для прикорма':'кабачок для прикорма','трекер ввода прикорма':'трекер прикорма','как готовить прикорм':'как приготовить пюре для прикорма','молочница у новорожденного во рту':'молочница у новорожденных','температура на зубы у ребенка':'температура при прорезывании зубов','новорожденный не спит ночью':'новорожденный не спит','ребенок 2 месяца не спит':'новорожденный не спит',  # дубль -> основная статья (спрос складывается)
 'мастит симптомы':'мастит','сцеживание молока':'сцеживание','сцеживание грудного молока':'сцеживание','молоко для новорожденных':'молоко при грудном вскармливании',
 'кормление грудью новорожденного':'как кормить грудью новорожденного','грудное кормление новорожденного':'как кормить грудью новорожденного','сон грудной ребенок':'сон новорожденного',
 'прикорм грудного ребенка':'прикорм при грудном вскармливании','прикорм во сколько':'во сколько вводить прикорм','питание новорожденного':'кормление новорожденного',
 'колики симптомы':'колики','колики в животе':'колики','кишечная колика':'колики','колики и газики':'газики у новорожденного','новорожденный срыгивает':'срыгивание',
 'новорожденный срыгивает после кормления':'срыгивание','смесь для кормления новорожденных':'смесь для новорожденных','сколько съедает новорожденный':'сколько должен съедать новорожденный',
 'вскармливание новорожденного':'кормление новорожденного','как кормить новорожденного':'кормление новорожденного','после кормления новорожденного':'кормление новорожденного',
 'болезнь розеола':'розеола','розеола сыпь':'розеола','ветрянка у детей симптомы':'ветрянка у детей','начало ветрянки у детей':'ветрянка у детей','желтуха у новорожденных':'желтушка у новорожденных',
 'ложным крупом':'ложный круп','дисплазия у новорожденных':'дисплазия тазобедренных суставов','дисплазия суставов у новорожденных':'дисплазия тазобедренных суставов',
 'тазобедренный сустав у новорожденных':'дисплазия тазобедренных суставов','звонок в скорую для детей':'скорая для детей','про скорую помощь для детей':'скорая для детей',
 'скорая помощь для детей':'скорая для детей','плачущий новорожденный':'новорожденный плачет','новорожденный кричит':'новорожденный плачет','ночной кашель у ребенка':'кашель ночью у ребенка',
 'симптомы пневмонии у ребенка':'пневмония у детей','гипертонус у новорожденных':'тонус у новорожденных','стоматит у детей во рту':'стоматит у детей','во сколько режутся зубы':'когда режутся зубы',
 'прорезывание молочных зубов':'прорезывание зубов','симптомы прорезывания зубов':'прорезывание зубов','скачки роста у новорожденных':'скачок роста у новорожденных',
 'калькулятор веса ребенка':'рассчитать вес ребенка','калькулятор роста ребенка':'рост ребенка','средний рост ребенка':'рост ребенка','рост и вес ребенка':'вес ребенка',
 'температура воды для купания новорожденного':'температура воды для новорожденных','температура для купания новорожденного':'температура воды для новорожденных',
 'как купать новорожденного':'купание новорожденного','большой родничок':'родничок','когда дети начинают говорить':'во сколько дети начинают говорить','ребенок начал ходить':'ребенок ходит',
 'в месяц новорожденный должен':'ребенок 1 месяц','месяц жизни новорожденного':'ребенок 1 месяц','сон месячного ребенка':'сон новорожденного','сколько должен спать новорожденный':'сон новорожденного',
 'время сна ребенка':'режим сна ребенка','новорожденный плохо спит':'новорожденный не спит','сдать анализы ребенку':'анализы детям','текут сопли у ребенка':'сопли у ребенка',
 'желтые сопли у ребенка':'зеленые сопли у ребенка','густые сопли у ребенка':'зеленые сопли у ребенка','ветрянка у детей симптомы ':'ветрянка у детей','рвота понос и температура у ребенка':'рвота и понос у ребенка',
 'кормление новорожденного':'кормление новорожденного','лучшая смесь для новорожденных':'смесь для новорожденных','лучшие каши для прикорма':'каши для прикорма','каша для новорожденных':'каши для прикорма',
 'как вводить кашу в прикорм':'каши для прикорма','как вводить яйцо в прикорм':'яйцо в прикорм','новорожденный не какает':'запор у новорожденного','сколько должен какать новорожденный':'стул новорожденного',
 'кал новорожденного':'стул новорожденного','жидкий стул у новорожденного':'стул новорожденного','стул на грудном вскармливании':'стул новорожденного',
}
rows = run(1000)
cand = collections.defaultdict(list); merged = {}
for r in rows:
    p = r['article_head']
    if re.search(JUNK, p): continue
    if p in MERGE and MERGE[p] != p:
        merged[MERGE[p]] = merged.get(MERGE[p], 0) + int(r['head_rf_30d']) + int(r['tail_rf_sum']); continue
    h, rev = hub_of(p)
    if h == 'Прочее': continue
    cand[h].append([h, p, rev, int(r['head_rf_30d']) + int(r['tail_rf_sum']), r['phrases'], r['top_tail']])
for h in cand:
    for x in cand[h]: x[3] += merged.get(x[1], 0)
    cand[h].sort(key=lambda x: -x[3])
take = {h: min(QUOTA.get(h, 0), len(cand[h])) for h in QUOTA}
spare = TARGET - sum(take.values())
while spare > 0:  # остаток квот — хабам, где есть ещё кандидаты, по спросу следующего кандидата
    opts = [(cand[h][take[h]][3], h) for h in take if take[h] < len(cand[h])]
    if not opts: break
    _, h = max(opts); take[h] += 1; spare -= 1
out = [x for h in take for x in cand[h][:take[h]]]
head = 1000
out.sort(key=lambda x: (-x[3]))
with open(os.path.join(ROOT, 'seo', '05-karta-300.csv'), 'w', newline='', encoding='utf-8') as f:
    w = csv.writer(f); w.writerow(['rank', 'hub', 'article_head', 'reviewer', 'demand_rf_30d', 'phrases', 'top_tail'])
    for i, x in enumerate(out, 1): w.writerow([i, *x])
c = collections.Counter(x[0] for x in out)
print(f'кандидаты от {head}; статей: {len(out)}; кандидатов всего по хабам:', {h: len(v) for h, v in cand.items()}); print(c.most_common())
